{
  "requests": [
    {
      "id": "r1",
      "text": "Hey, picking this up from where Dana left it. Billing looks wrong to me. First, recolour Billing to purple, that's the finance team's colour. Then Ledger should sit right below Billing, and connect Billing and Ledger with a two-way arrow since they sync both ways. Orders sends events to Billing, so add an arrow from Orders to Billing. Notify is not used anymore, remove it. Hmm, can you tell me which shapes are still connected to Gateway? Also make Users a bit bigger, it's hard to read. And Orders should be an ellipse, I think. Thanks!",
      "do": "create",
      "args": {
        "shape": "ellipse",
        "kind": "shape",
        "color": "purple",
        "position": "right",
        "anchor": [
          {
            "name": "Gateway"
          },
          {
            "name": "Billing"
          }
        ],
        "layout": "row"
      }
    },
    {
      "id": "r2",
      "text": "make Users a bit bigger, it's hard to read.",
      "do": "label",
      "args": {
        "kind": "shape",
        "label": "Users",
        "position": "center",
        "notColor": "black"
      }
    },
    {
      "id": "r3",
      "text": "Orders should be an ellipse, I think.",
      "do": "create",
      "args": {
        "shape": "ellipse",
        "kind": "shape",
        "color": "orange",
        "position": "right",
        "anchor": [
          {
            "name": "Orders"
          }
        ],
        "layout": "row"
      }
    },
    {
      "id": "r4",
      "text": "Which shape is the leftmost now?",
      "do": "extreme",
      "args": {
        "superlative": "leftmost"
      }
    },
    {
      "id": "r5",
      "text": "can you tell me which shapes are still connected to Gateway?",
      "do": "list",
      "args": {
        "shape": "any",
        "kind": "shape",
        "position": "center",
        "anchor": [
          {
            "name": "Gateway"
          }
        ]
      }
    },
    {
      "id": "r6",
      "text": "Also make Users a bit bigger, it's hard to read.",
      "do": "label",
      "args": {
        "kind": "shape",
        "label": "Users",
        "position": "center",
        "notColor": "black"
      }
    }
  ],
  "not_understood": [
    "shapes",
    "properties"
  ]
}

