{
  "requests": [
    {
      "id": "r1",
      "text": "Hi! Quick restructuring of the microservices diagram. First, get rid of Queue, we moved to direct calls. Actually no, keep Queue for now, just disconnect Cart from it. Next, draw arrows from Bff to Catalog, Cart and Payments. Payments should be green. Put Frontend at the top, above everything else. Who is connected to Bff after that? And is Payments bigger than Cart? Thanks a lot.",
      "do": "arrange",
      "args": {
        "template": "target",
        "title": "microservices",
        "items": [
          "Frontend",
          "Bff",
          "Catalog",
          "Cart",
          "Payments",
          "Queue"
        ],
        "position": "top",
        "direction": "up",
        "axis": "vertical",
        "layout": "row"
      }
    },
    {
      "id": "r2",
      "text": "Who is connected to Bff after that?",
      "do": "connect",
      "args": {
        "from": [
          {
            "name": "Bff"
          }
        ],
        "to": [
          {
            "name": "Cart"
          },
          {
            "name": "Payments"
          }
        ],
        "style": "solid",
        "arrow": "both"
      }
    },
    {
      "id": "r3",
      "text": "Is Payments bigger than Cart?",
      "do": "extreme",
      "args": {
        "superlative": "biggest",
        "target": [
          {
            "name": "Payments"
          },
          {
            "name": "Cart"
          }
        ]
      }
    }
  ],
  "not_understood": [
    "Who is connected to Bff after that?",
    "Is Payments bigger than Cart?"
  ]
}

