{
  "requests": [
    {
      "id": "r1",
      "text": "Quick sanity check of the home office drawing before I print it. Is there anything near Router? I have a feeling Printer is crowding it. Move Printer to the bottom left. Is Ap connected to Router? It should be. If not, draw a plain line between them. Pc1 and Pc2 are both laptops, make them small white rectangles and put them next to Ap. Which shape is farthest from Router? Is Nas a square? It should be a hexagon, change it. Okay thanks.",
      "do": "extreme",
      "args": {
        "superlative": "farthest"
      }
    },
    {
      "id": "r2",
      "text": "Is Nas a square? It should be a hexagon, change it.",
      "do": "label",
      "args": {
        "kind": "shape",
        "label": "Nas",
        "target": [{"name": "Router"}]
      }
    },
    {
      "id": "r3",
      "text": "Okay thanks.",
      "do": "help",
      "args": {
        "about": "a text"
      }
    },
    {
      "id": "r4",
      "text": "Move Printer to the bottom left.",
      "do": "move",
      "args": {
        "target": [{"name": "Printer"}],
        "direction": "left",
        "distance": 0
      }
    },
    {
      "id": "r5",
      "text": "Is Ap connected to Router? It should be.",
      "do": "connect",
      "args": {
        "color": "white",
        "label": "Ap",
        "target": [{"name": "Router"}]
      }
    },
    {
      "id": "r6",
      "text": "If not, draw a plain line between them.",
      "do": "connect",
      "args": {
        "color": "white",
        "label": "Ap",
        "target": [{"name": "Router"}]
      }
    },
    {
      "id": "r7",
      "text": "Pc1 and Pc2 are both laptops, make them small white rectangles and put them next to Ap.",
      "do": "duplicate",
      "args": {
        "count": 2,
        "target": [{"name": "Ap"}]
      }
    },
    {
      "id": "r8",
      "text": "Which shape is farthest from Router? Is Nas a square? It should be a hexagon, change it.",
      "do": "extreme",
      "args": {
        "superlative": "farthest"
      }
    }
  ],
  "not_understood": []
}
